import Slider from "@mui/material/Slider";
import { styled, useTheme } from "@mui/material/styles";
import { useMediaQuery } from "@mui/material";
import { hexToRgba } from "utils/utils";

import { synthCyberPink } from "interactivity/resources/constants/colors";

const cyberPink = hexToRgba(synthCyberPink);

const StyledSlider = styled(Slider)({
  color: cyberPink,
  width: "100%",
  marginTop: 8,
  ".MuiSlider-markLabel": {
    color: cyberPink,
  },
});

// On small screens, strip label text from marks so they don't overflow.
// Tick positions are preserved; the floating tooltip still shows the value.
const stripMarkLabels = (marks) => {
  if (!marks || typeof marks === "boolean") return marks;
  return marks.map(({ value }) => ({ value }));
};

export const CustomSlider = ({ marks, ...props }) => {
  const theme = useTheme();
  const isSmall = useMediaQuery(theme.breakpoints.down("sm"));
  const responsiveMarks = isSmall ? stripMarkLabels(marks) : marks;

  return (
    <StyledSlider
      marks={responsiveMarks}
      valueLabelDisplay={isSmall ? "on" : props.valueLabelDisplay ?? "auto"}
      {...props}
    />
  );
};
